use usage

use premium

record Rental
start:i duration:i base_rate:i extra_rate:i

record Receipt
end_minute:i cents:i

invoice rental:{Rental} > {Receipt}
let slot period (get start rental) (get duration rental)
let base usage_charge slot (get base_rate rental)
let extra premium_charge slot (get extra_rate rental)
make Receipt end_minute (get stop slot) cents (+ base extra)

main rentals:*{Rental} > *{Receipt}
fold rentals (list {Receipt} 0) receipts row rental append receipts (invoice rental)

